ower(coalesce(a.channel,b.channel)) ) ) website_revenue from maplemonk.KA_MARKETING_CONSOLIDATED_INTERMEDIATE a full outer join (select cast(order_timestamp as date) date ,final_utm_campaign campaign_name ,upper(case when lower(final_utm_channel) like any (\'%paid social%\',\'%facebook%\', \'%instagram%\',\'%ig%\',\'%fb%\') then \'Facebook\' when lower(final_utm_channel) like (\'%google%\') then \'Google\' end) channel ,sum(total_sales) website_revenue from maplemonk.KA_SHOPIFY_FACT_ITEMS where final_utm_channel is not null group by 1,2,3 ) b on lower(a.campaign_name) = lower(b.campaign_name) and a.date = b.date and lower(a.channel) = lower(b.channel);",
